import "./ripple.js";
import { registerStyles } from "../styles.js";
registerStyles({ "badge": ".mtrl-badge__wrapper{position:relative;display:inline-flex;flex-shrink:0}.mtrl-badge{position:absolute;display:flex;align-items:center;justify-content:center;font-weight:500;box-sizing:border-box;overflow:hidden;transition:all 200ms ease;text-overflow:ellipsis}.mtrl-badge--invisible{display:none}.mtrl-badge--small{width:6px;height:6px;min-width:6px;border-radius:var(--mtrl-sys-shape-corner-full, 9999px);font-size:0;padding:0}.mtrl-badge--large{height:16px;min-width:16px;border-radius:var(--mtrl-sys-shape-corner-full, 9999px);padding:0 4px;font-size:11px;line-height:16px;padding-top:.5px}.mtrl-badge--large.mtrl-badge--overflow{min-width:auto;max-width:34px;padding:0 4px}.mtrl-badge--positioned.mtrl-badge--small.mtrl-badge--top-right{top:-3px;right:-3px}.mtrl-badge--positioned.mtrl-badge--small.mtrl-badge--top-left{top:-3px;left:-3px}.mtrl-badge--positioned.mtrl-badge--small.mtrl-badge--bottom-right{bottom:-3px;right:-3px}.mtrl-badge--positioned.mtrl-badge--small.mtrl-badge--bottom-left{bottom:-3px;left:-3px}.mtrl-badge--positioned.mtrl-badge--large.mtrl-badge--top-right{top:-8px;right:-8px}.mtrl-badge--positioned.mtrl-badge--large.mtrl-badge--top-left{top:-8px;left:-8px}.mtrl-badge--positioned.mtrl-badge--large.mtrl-badge--bottom-right{bottom:-8px;right:-8px}.mtrl-badge--positioned.mtrl-badge--large.mtrl-badge--bottom-left{bottom:-8px;left:-8px}.mtrl-badge--error{background-color:var(--mtrl-sys-color-error);color:var(--mtrl-sys-color-on-error)}.mtrl-badge--primary{background-color:var(--mtrl-sys-color-primary);color:var(--mtrl-sys-color-on-primary)}.mtrl-badge--secondary{background-color:var(--mtrl-sys-color-secondary);color:var(--mtrl-sys-color-on-secondary)}.mtrl-badge--tertiary{background-color:var(--mtrl-sys-color-tertiary);color:var(--mtrl-sys-color-on-tertiary)}.mtrl-badge--success{background-color:var(--mtrl-sys-color-success);color:var(--mtrl-sys-color-on-success)}.mtrl-badge--warning{background-color:var(--mtrl-sys-color-warning);color:var(--mtrl-sys-color-on-warning)}.mtrl-badge--info{background-color:var(--mtrl-sys-color-info);color:var(--mtrl-sys-color-on-info)}:where(.mtrl-rtl) .mtrl-badge--positioned.mtrl-badge--top-right,:where(:host(.mtrl-rtl)) .mtrl-badge--positioned.mtrl-badge--top-right,[dir=rtl] .mtrl-badge--positioned:not(:where(.mtrl-ltr,.mtrl-ltr *)).mtrl-badge--top-right{right:auto;left:-8px}:where(.mtrl-rtl) .mtrl-badge--positioned.mtrl-badge--top-left,:where(:host(.mtrl-rtl)) .mtrl-badge--positioned.mtrl-badge--top-left,[dir=rtl] .mtrl-badge--positioned:not(:where(.mtrl-ltr,.mtrl-ltr *)).mtrl-badge--top-left{left:auto;right:-8px}:where(.mtrl-rtl) .mtrl-badge--positioned.mtrl-badge--bottom-right,:where(:host(.mtrl-rtl)) .mtrl-badge--positioned.mtrl-badge--bottom-right,[dir=rtl] .mtrl-badge--positioned:not(:where(.mtrl-ltr,.mtrl-ltr *)).mtrl-badge--bottom-right{right:auto;left:-8px}:where(.mtrl-rtl) .mtrl-badge--positioned.mtrl-badge--bottom-left,:where(:host(.mtrl-rtl)) .mtrl-badge--positioned.mtrl-badge--bottom-left,[dir=rtl] .mtrl-badge--positioned:not(:where(.mtrl-ltr,.mtrl-ltr *)).mtrl-badge--bottom-left{left:auto;right:-8px}" });
